import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"21、【噬嗑】 震下离上","description":"周易尚氏学 - 21、【噬嗑】 震下离上","frontmatter":{"title":"21、【噬嗑】 震下离上","description":"周易尚氏学 - 21、【噬嗑】 震下离上"},"headers":[],"relativePath":"zh/classics/shangshi/026.md","filePath":"zh/classics/shangshi/026.md"}'),h={name:"zh/classics/shangshi/026.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_21、【噬嗑】-震下离上" tabindex="-1">21、【噬嗑】 震下离上 <a class="header-anchor" href="#_21、【噬嗑】-震下离上" aria-label="Permalink to “21、【噬嗑】 震下离上”">​</a></h1><p>噬嗑也。嗑合也。亨通也。夫上下之不能相合者。中必有物间之。嗑而去其间。则合而通矣。国家之有刑狱。亦复如是。民有梗化者。以刑克之。则顽梗去。而上下通矣。故曰利用狱。震为口。颐利求口实是也。为口故曰噬。雷电合居于东。故曰合而重。震为口。初至四。正反震口合。上离。正反兑口合。故曰噬嗑。自覆象失传。及震为口之象亡。噬嗑之义。遂晦而不明。卦一阴一阳。刚柔交。故曰亨。坎为狱。折狱之道。不明则人不服。不威则众不从。今威明并济。故利。</p><p>彖曰。颐中有物曰噬嗑。噬嗑而亨。刚柔分。动而明。雷电合而童。柔得中而上行。虽不当位。利用狱也。</p><p>有物谓四。四在顾中。故曰有物。颐上下阳。中四交皆阴。阴顺阳。故求得口食。今四阳横互于中。阳遇阳为仇为敌。不顺。嗑去此物。则合而通。故曰噬嗑而亨。卦阳爻与阴交相间。故曰刚柔分。雷电合居于东。故曰合而章。五不当位。然文明以中。断制枉直。不失情理。故利用狱也。</p><p>象曰。雷电。噬嗑。先王以明罚敕法。</p><p>罚法皆坎象。敕（右力）正也。威之用。明则离之用也，</p><p>初九。屦校减趾。无咎。</p><p>震为趾。坎为校。初临重阴。利往。往而遇坎。坎在震上。故曰屦校。校械也。屦贯也。言以械贯于震足之上。足不见。故曰减趾。初当位。故无咎。</p><h3 id="象日。屦校减趾。不行也。" tabindex="-1">象日。屦校减趾。不行也。 <a class="header-anchor" href="#象日。屦校减趾。不行也。" aria-label="Permalink to “象日。屦校减趾。不行也。”">​</a></h3><p>此言人初有过。其过尚微。故罚亦从轻。使有所惩。而不至积累其罪。以至于诛。所谓小惩大戒也。初本利行。行而遇险。故不行。</p><p>六二。噬肤减鼻。无咎。</p><p>震为噬。二艮体。故曰肤。曰鼻。言艮肤艮鼻。为震口所噬。隐伏于坎水之下。故曰减。二乘刚。故有是象。按减趾有类于刖刑。减鼻有类于劓刑。皆初犯罪。刑之轻者。皆冀其有所惩于后也。二得中。故可免于咎。</p><h3 id="象曰。噬肤减鼻。乘刚也。" tabindex="-1">象曰。噬肤减鼻。乘刚也。 <a class="header-anchor" href="#象曰。噬肤减鼻。乘刚也。" aria-label="Permalink to “象曰。噬肤减鼻。乘刚也。”">​</a></h3><p>乘刚不顺。</p><p>六三。噬腊肉。遇毒。小吝。无咎。</p><p>说文腊乾肉也。民坚故曰腊。坎为肉。故三爻四爻五爻皆言肉。坎为毒。遇毒者。坎在前也。坎肉象。详焦氏易诂然有应故小识破。无咎。王弼曰。噬以喻刑人。腊以喻不服。毒以喻怨生。按三不当位。以斯用刑。民必不服。岂惟不服。怨毒以生。言小民不知惩戒。仍积恶不俊也。</p><h3 id="象曰。遇毒。" tabindex="-1">象曰。遇毒。 <a class="header-anchor" href="#象曰。遇毒。" aria-label="Permalink to “象曰。遇毒。”">​</a></h3><p>位不当也。三阳位。</p><p>九四。噬乾胏。得金矢。利艰贞。吉。</p><p>胏。玉篇。肉带骨也。离艮皆为火。坎肉居中。故曰干胏。艮为金。坎为矢。详焦氏易诂四艮主爻。故曰金。亦坎主爻。故曰金矢。坎陷故利艰贞。按周礼大司寇以两造两剂。禁民狱讼。人束矢钧金。然后听之。兹云得金矢。仍寓止讼之意。夫今民人金矢。原欲止其狱讼。兹曰得金矢。是讼者不止。而益深其罪也。</p><h3 id="象曰。利艰贞吉。未光也。" tabindex="-1">象曰。利艰贞吉。未光也。 <a class="header-anchor" href="#象曰。利艰贞吉。未光也。" aria-label="Permalink to “象曰。利艰贞吉。未光也。”">​</a></h3><p>坎隐伏故曰未光。升五则光矣。</p><p>六五。噬乾肉。得黄金。贞厉。无咎。</p><p>离火故仍曰乾肉。离色黄。五履艮金上。故曰得黄金。贞卜问。失位。故贞厉。得中。故无咎。按五位虽尊。然不当位。以斯噬物。物亦不服。其坚有如噬乾肉之难。夫据尊位。能行其戮者也。乃物仍不服。不知诫惧。则其估恶不俊（左心）。顽坚难化也明矣。故曰得黄金。言其坚愈进也。得黄金非吉辞。如吉则下不日贞厉矣。</p><h3 id="象曰。贞厉无咎。得当也" tabindex="-1">象曰。贞厉无咎。得当也 <a class="header-anchor" href="#象曰。贞厉无咎。得当也" aria-label="Permalink to “象曰。贞厉无咎。得当也”">​</a></h3><p>得当者。得中也。</p><h3 id="上九。何校严耳。凶。" tabindex="-1">上九。何校严耳。凶。 <a class="header-anchor" href="#上九。何校严耳。凶。" aria-label="Permalink to “上九。何校严耳。凶。”">​</a></h3><p>坎为校为耳。上应在三。三坎体亦艮体。良为背为何。坎校在民背上。耳则遮矣。故曰严耳。易爻在此。而象全在应。此其一也。王弼曰处罚之极。恶积不改者也。罪非所惩。故刑及其首。及首非诫。减耳非惩。凶莫甚焉。正义曰。罪未及首。犹可戒惧归善。罪已及首。性命将尽。非复可戒。故云及首非戒也。校既灭耳。将欲刑杀。非可惩改。故云灭耳非惩也。</p><h3 id="象曰。何校又耳。聪不明也。" tabindex="-1">象曰。何校又耳。聪不明也。 <a class="header-anchor" href="#象曰。何校又耳。聪不明也。" aria-label="Permalink to “象曰。何校又耳。聪不明也。”">​</a></h3><p>灭耳则有害于聪。故曰不明。</p>',30)])])}const f=e(h,[["render",s]]);export{_ as __pageData,f as default};
